export function partyInitials(name: string): string {
  const stripped = name.replace(/^Partai\s+/i, '');
  if (stripped === stripped.toUpperCase() && stripped.length <= 5) return stripped;
  return stripped
    .split(' ')
    .map((w) => w[0])
    .join('')
    .toUpperCase()
    .slice(0, 4);
}

